import {
  applyAutoAbandonMetadata,
  appendEvent,
  createSession,
  getSession,
  getSessionEventsPath,
  resolveStaleSessionCriteria,
  selectStaleActiveSessions,
} from "../src/sessions/store.js";

describe("stale session criteria", () => {
