    expect(applied.updates[0].closeReason).toContain("older-than=24h");

    expect(after?.status).toBe(before?.status);
    expect(after?.ended_at).toBe(before?.ended_at);
    expect(after?.close_reason).toBe(before?.close_reason);
  });
