    expect(result.evaluations[0].meetsInactivityThreshold).toBe(true);
    expect(result.evaluations[0].blockedByLivenessGuard).toBe(true);
    expect(result.candidates).toHaveLength(0);
  });

  // AC: @session-stale-close-metadata ac-1
