      type: 'session.start',
      session_id: '01KF123456789ABCDEFGHJKMNP',
      trace_id: 'trace-123',
      data: { message: 'Session started' },
    };

    const result = SessionEventSchema.safeParse(event);
    expect(result.success).toBe(true);
  });

