      await createSession(testDir, { id: 'session-b', agent_type: 'claude-code' });
      await createSession(testDir, { id: 'session-c', agent_type: 'test-agent' });

      const sessions = await listSessions(testDir);

      expect(sessions).toHaveLength(3);
