      expect(result.stderr).toBe('');
      expect(result.stdout_path).toBeUndefined();
      expect(result.stderr_path).toBeUndefined();
      expect(result.preview_truncated).toBe(false);
    } finally {
      await fs.rm(tempDir, { recursive: true, force: true });
    }
  });
