      const renderer = createPrefixedRenderer('[TEST]');

      // Spy on console.log to capture what the wrapper passes to the original
      const logCalls: unknown[][] = [];
      const spy = vi.spyOn(console, 'log').mockImplementation((...args: unknown[]) => {
